// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address successor;

    function setUp() public {
        c = new C();
        successor = address(new Successor());
    }

    function testFuzz_property(address from, address to, uint256 amount) public {
        // Build dynamic arrays from fuzzed length to avoid "too many assumes"
        // but use a single element to keep the domain simple and effective.
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint256[] memory values = new uint256[](1);
        values[0] = amount;

        // Ensure we are calling the successor that always returns true for transferFrom
        bool success = c.transfer(from, successor, tos, values);

        // For the reference, this always returns true because the successor succeeds.
        // For the mutant, this always returns false because it returns false regardless.
        // The assertion checks that the return value is true, which holds for reference but fails for mutant.
        assertTrue(success);
    }
}

contract Successor {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}

