pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address[] memory _tos, uint[] memory v) public {
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // deploy adversarial callee that always reverts on transferFrom
        Reverter reverter = new Reverter();
        // attempt transfer through the adversarial address
        bool ok;
        try c.transfer(from, address(reverter), _tos, v) returns (bool ret) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}
contract Reverter {
    fallback() external payable { revert(); }
}
